import jakarta.persistence.LockModeType;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.Optional;
import java.util.UUID;

public interface LoanJpaRepository extends JpaRepository<LoanJpaEntity, UUID> {

    long countByMemberIdAndReturnedAtIsNull(UUID memberId);

    // 도서 제목을 얻으려고 book 과 조인한다. 정렬 키가 같은 대출끼리도 페이지가 겹치지 않도록 id 로 정렬을 고정한다
    @Query(value = """
            select new com.example.lending.adapter.out.persistence.ActiveLoanRow(l.id, b.id, b.title, l.loanedAt, l.dueAt)
            from LoanJpaEntity l, BookJpaEntity b
            where b.id = l.bookId and l.memberId = :memberId and l.returnedAt is null
            order by l.loanedAt asc, l.id asc
            """,
            countQuery = """
            select count(l) from LoanJpaEntity l
            where l.memberId = :memberId and l.returnedAt is null
            """)
    Page<ActiveLoanRow> findActiveLoans(@Param("memberId") UUID memberId, Pageable pageable);

    // 같은 대출에 대한 동시 반납 요청을 직렬화하기 위해 트랜잭션 안에서 행 잠금을 건다
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select l from LoanJpaEntity l where l.id = :id")
    Optional<LoanJpaEntity> findByIdForUpdate(@Param("id") UUID id);
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SearchBookPort;
import com.example.lending.domain.Book;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.UUID;

@Component
public class BookPersistenceAdapter implements LoadBookPort, SaveBookPort, SearchBookPort {

    private final BookJpaRepository bookJpaRepository;
    private final BookMapper bookMapper = new BookMapper();

    public BookPersistenceAdapter(BookJpaRepository bookJpaRepository) {
        this.bookJpaRepository = bookJpaRepository;
    }

    @Override
    public Optional<Book> loadBook(UUID bookId) {
        return bookJpaRepository.findById(bookId).map(bookMapper::toDomain);
    }

    @Override
    public Optional<Book> loadBookForUpdate(UUID bookId) {
        return bookJpaRepository.findByIdForUpdate(bookId).map(bookMapper::toDomain);
    }

    @Override
    public void saveBook(Book book) {
        bookJpaRepository.save(bookMapper.toEntity(book));
    }

    @Override
    public List<Book> searchByTitle(String keyword) {
        return bookJpaRepository.findByLowerTitleLike(toLikePattern(keyword)).stream()
                .map(bookMapper::toDomain)
                .toList();
    }

    // 검색어 안의 % 와 _ 가 와일드카드로 해석되지 않도록 '!' 로 이스케이프한다
    private String toLikePattern(String keyword) {
        String escaped = keyword.toLowerCase(Locale.ROOT)
                .replace("!", "!!")
                .replace("%", "!%")
                .replace("_", "!_");
        return "%" + escaped + "%";
    }
}
