            order by l.loanedAt asc, l.id asc
            """,
            countQuery = """
            select count(l) from LoanJpaEntity l
            where l.memberId = :memberId and l.returnedAt is null
            """)
    Page<ActiveLoanRow> findActiveLoans(@Param("memberId") UUID memberId, Pageable pageable);

