    public ReservationResponse reserveBook(@PathVariable UUID bookId, @RequestBody ReserveBookRequest request) {
        Placement placement = reserveBookUseCase.reserveBook(new ReserveBookCommand(bookId, request.memberId()));
        return ReservationResponse.from(placement);
    }

    // 소진된 예약은 포함하지 않는다. 맨 앞 예약자가 position 1 이다
    @GetMapping("/{bookId}/reservations")
    public List<BookReservationResponse> getReservations(@PathVariable UUID bookId) {
        List<Reservation> reservations = getBookReservationsUseCase.getReservations(
                new GetBookReservationsQuery(bookId));
        return IntStream.range(0, reservations.size())
                .mapToObj(i -> BookReservationResponse.of(reservations.get(i), i + 1))
                .toList();
    }
}

