package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.DiscardBookUseCase;
import com.example.lending.application.port.in.DiscardBookUseCase.DiscardBookCommand;
import com.example.lending.application.port.in.GetBookReservationsUseCase;
import com.example.lending.application.port.in.GetBookReservationsUseCase.GetBookReservationsQuery;
import com.example.lending.application.port.in.RegisterBookUseCase;
import com.example.lending.application.port.in.RegisterBookUseCase.RegisterBookCommand;
import com.example.lending.application.port.in.ReserveBookUseCase;
import com.example.lending.application.port.in.ReserveBookUseCase.Placement;
import com.example.lending.application.port.in.ReserveBookUseCase.ReserveBookCommand;
import com.example.lending.application.port.in.SearchBooksUseCase;
import com.example.lending.application.port.in.SearchBooksUseCase.SearchBooksQuery;
import com.example.lending.domain.Book;
import com.example.lending.domain.Reservation;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;
import java.util.stream.IntStream;

@RestController
@RequestMapping("/books")
public class BookController {

    private final RegisterBookUseCase registerBookUseCase;
    private final SearchBooksUseCase searchBooksUseCase;
    private final DiscardBookUseCase discardBookUseCase;
    private final ReserveBookUseCase reserveBookUseCase;
    private final GetBookReservationsUseCase getBookReservationsUseCase;

    public BookController(RegisterBookUseCase registerBookUseCase, SearchBooksUseCase searchBooksUseCase,
                          DiscardBookUseCase discardBookUseCase, ReserveBookUseCase reserveBookUseCase,
                          GetBookReservationsUseCase getBookReservationsUseCase) {
        this.registerBookUseCase = registerBookUseCase;
        this.searchBooksUseCase = searchBooksUseCase;
        this.discardBookUseCase = discardBookUseCase;
        this.reserveBookUseCase = reserveBookUseCase;
        this.getBookReservationsUseCase = getBookReservationsUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public BookResponse registerBook(@RequestBody RegisterBookRequest request) {
        Book book = registerBookUseCase.registerBook(new RegisterBookCommand(request.title()));
        return BookResponse.from(book);
    }

    // 제목에 검색어가 포함된 도서를 대소문자 구분 없이 조회한다
    @GetMapping
    public List<BookResponse> searchBooks(@RequestParam String title) {
        return searchBooksUseCase.searchBooks(new SearchBooksQuery(title)).stream()
                .map(BookResponse::from)
                .toList();
    }

    // 훼손되거나 분실된 도서를 폐기한다. 폐기된 도서는 더 이상 대출할 수 없다
    @PostMapping("/{bookId}/discard")
    public BookResponse discardBook(@PathVariable UUID bookId) {
        Book book = discardBookUseCase.discardBook(new DiscardBookCommand(bookId));
        return BookResponse.from(book);
    }
}

