package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ReservationIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reservations_on_a_loaned_book_are_queued_in_order() throws Exception {
        String book = registerBook();
        loan(book, registerMember());
        String first = registerMember();
        String second = registerMember();

        mockMvc.perform(reserve(book, first))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.reservationId").isNotEmpty())
                .andExpect(jsonPath("$.position").value(1));
        mockMvc.perform(reserve(book, second))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(2));

        mockMvc.perform(get("/books/{bookId}/reservations", book))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].memberId").value(first))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].memberId").value(second))
                .andExpect(jsonPath("$[1].position").value(2));
    }

    @Test
    void reserving_an_available_book_returns_409() throws Exception {
        mockMvc.perform(reserve(registerBook(), registerMember()))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reserving_a_discarded_book_returns_409() throws Exception {
        String book = registerBook();
        mockMvc.perform(post("/books/{bookId}/discard", book)).andExpect(status().isOk());

        mockMvc.perform(reserve(book, registerMember()))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void reserving_the_same_book_twice_returns_409() throws Exception {
        String book = registerBook();
        loan(book, registerMember());
        String member = registerMember();
        mockMvc.perform(reserve(book, member)).andExpect(status().isCreated());

        mockMvc.perform(reserve(book, member))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RESERVED"));
    }

    @Test
    void reserving_with_unknown_book_or_member_returns_404() throws Exception {
        mockMvc.perform(reserve(UUID.randomUUID().toString(), registerMember()))
                .andExpect(status().isNotFound());

        String book = registerBook();
        loan(book, registerMember());
        mockMvc.perform(reserve(book, UUID.randomUUID().toString()))
                .andExpect(status().isNotFound());
    }

    @Test
    void listing_reservations_for_unknown_book_returns_404() throws Exception {
        mockMvc.perform(get("/books/{bookId}/reservations", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void non_front_member_cannot_borrow_a_returned_book_while_it_is_reserved() throws Exception {
        String book = registerBook();
        String loanId = loan(book, registerMember());
        reserveAs(book, registerMember());
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(book, registerMember())))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));
    }

    @Test
    void front_reserver_borrows_a_returned_book_and_leaves_the_queue() throws Exception {
        String book = registerBook();
        String loanId = loan(book, registerMember());
        String front = registerMember();
        String second = registerMember();
        String frontReservationId = reserveAs(book, front);
        reserveAs(book, second);
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(book, front)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.memberId").value(front));

        mockMvc.perform(get("/books/{bookId}/reservations", book))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].memberId").value(second))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[?(@.reservationId == '" + frontReservationId + "')]").isEmpty());
    }

    @Test
    void next_in_queue_is_reserved_for_after_the_front_reserver_borrows() throws Exception {
        String book = registerBook();
        String loanId = loan(book, registerMember());
        String front = registerMember();
        String second = registerMember();
        reserveAs(book, front);
        reserveAs(book, second);
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());
        String frontLoanId = loanId(book, front);
        mockMvc.perform(post("/loans/{loanId}/return", frontLoanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(book, registerMember())))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(book, second)))
                .andExpect(status().isCreated());
    }

    @Test
    void reserved_book_on_loan_cannot_be_borrowed_by_the_front_reserver_yet() throws Exception {
        String book = registerBook();
        loan(book, registerMember());
        String front = registerMember();
        reserveAs(book, front);

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(book, front)))
                .andExpect(status().isConflict());
    }

    private org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder reserve(String bookId,
                                                                                              String memberId)
            throws Exception {
        return post("/books/{bookId}/reservations", bookId)
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(Map.of("memberId", memberId)));
    }

    private String reserveAs(String bookId, String memberId) throws Exception {
        String reserved = mockMvc.perform(reserve(bookId, memberId))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(reserved).get("reservationId").asText();
    }

    private String loan(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String loanId(String bookId, String memberId) throws Exception {
        return loan(bookId, memberId);
    }

    private String loanRequest(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId));
    }

    private String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"이준호\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }
}

